package nhom10.phonenest.entity;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import nhom10.phonenest.enums.TrangThaiDonHang; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="DonHang") @Getter @Setter
public class DonHang { @Id private String maDonHang; @ManyToOne @JoinColumn(name="maKh",nullable=false) private KhachHang khachHang; @ManyToOne @JoinColumn(name="maKm") private KhuyenMai khuyenMai; @ManyToOne @JoinColumn(name="maKmVanChuyen") private KhuyenMai khuyenMaiVanChuyen; private String tenNguoiNhan; private String soDienThoaiNhan; private String diaChiGiaoHang; private BigDecimal tamTinh=BigDecimal.ZERO; private BigDecimal giamGia=BigDecimal.ZERO; private BigDecimal phiVanChuyen=BigDecimal.ZERO; private BigDecimal giamPhiVanChuyen=BigDecimal.ZERO; private BigDecimal tongThanhToan=BigDecimal.ZERO; private LocalDateTime ngayMua; private LocalDateTime ngayCapNhat; private LocalDateTime ngayGiao; @Enumerated(EnumType.STRING) private TrangThaiDonHang trangThai=TrangThaiDonHang.CHO_XAC_NHAN; private String ghiChu; @OneToMany(mappedBy="donHang",cascade=CascadeType.ALL,orphanRemoval=true) private List<ChiTietDonHang> chiTiet=new ArrayList<>(); }
